stringcontrol.script:
function onInit()
	DB.addHandler(DB.getPath(window.getDatabaseNode(), "classes"), "onChildUpdate", update);
	update();
end
function onClose()
	DB.removeHandler(DB.getPath(window.getDatabaseNode(), "classes"), "onChildUpdate", update);
end
function update()
	setValue(CCLevelUp.describeSecondClass(window.getDatabaseNode()));
end

windowclass.script:
function onInit()
	DB.addHandler(DB.getPath(getDatabaseNode()), "onChildUpdate", update);
	update();
end
function onClose()
	DB.removeHandler(DB.getPath(getDatabaseNode()), "onChildUpdate", update);
end
function update()
	local node = getDatabaseNode();
	title.setValue("Class & Level - " .. DB.getValue(node, "name", ""));
	level.setValue(tostring(DB.getValue(node, "classes.slot1.level", 0)));
	exp.setValue(tostring(DB.getValue(node, "exp", 0)));
	expnext.setValue(tostring(DB.getValue(node, "expneeded", 0)));
	list.closeAll();
	for _, t in ipairs(CCLevelUp.getClassRows(node)) do
		local w = list.createWindow();
		w.name.setValue(t.name);
		w.level.setValue(tostring(t.level));
		w.note.setValue(t.note or "");
	end
end

function onInit()
	CCLevelUp.registerWindow(self);
end
function onClose()
	CCLevelUp.unregisterWindow(self);
end

local _sPath = "";
local _bNew = false;
local _bChosen = false;
function setEntry(t, bChosen)
	_sPath = t.slot;
	name.setValue(t.name);
	rule.setValue(t.note or "");
	if bChosen then
		level.setValue(string.format("Level %d -> %d", CCLevelUp.getFromLevel(), CCLevelUp.getToLevel()));
		go.setStateText(0, "Cancel");
	else
		level.setValue(string.format("Level %d", t.level));
		go.setStateText(0, "Level Up");
	end
	go.setVisible(t.canlevel and true or false);
	reclass.setVisible(false);
	_bChosen = bChosen;
end
function setNewClass(t)
	_sPath = DB.getPath(t.node);
	name.setValue(DB.getValue(t.node, "name", ""));
	level.setValue(t.code ~= "" and ("[" .. t.code .. "]") or "");
	rule.setValue(t.rule);
	go.setStateText(0, "Add Class");
	go.setVisible(t.allowed);
	_bNew = true;
end
function onGo()
	if _bNew then
		CCLevelUp.chooseDualClass(_sPath);
	elseif _bChosen then
		CCLevelUp.cancelChoice();
	else
		CCLevelUp.chooseLevelUp(_sPath);
	end
end
function onReclass()
	CCLevelUp.chooseReclass(_sPath);
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("cclevelup_steps_class"));
	onPageShow();
end
function onPageShow()
	local nodeChar = CCLevelUp.getChar();
	local nodeTarget = CCLevelUp.getTarget();
	local L = CCLevelUp.getState();
	classes.closeAll();
	for _, t in ipairs(CCLevelUp.getClassRows(nodeChar)) do
		local bChosen = L.mode == "levelup" and L.slot == t.slot;
		if not nodeTarget or bChosen then
			classes.createWindow().setEntry(t, bChosen);
		end
	end
	-- Once a class is chosen: only what the new level brings, as cards.
	cards.closeAll();
	chosen_header.setVisible(nodeTarget ~= nil);
	cards.setVisible(nodeTarget ~= nil);
	if nodeTarget then
		local tModes = { dual = "Add Class (dual class): ", reclass = "Reclass to " };
		chosen_header.setValue((tModes[L.mode] or "") .. DB.getValue(nodeTarget, "name", ""):upper() .. " " .. CCLevelUp.getToLevel());
		for _, t in ipairs(CCLevelUp.getFeatureCards()) do
			cards.createWindow().setData(t.title, t.text, t.open);
		end
	end
	-- Dual class and reclass (Adventurer's Backpack).
	local bOk, sWhy = CCLevelUp.canAddClass();
	local bNewMode = L.mode == "dual" or L.mode == "reclass";
	newclasses.closeAll();
	dual_note.setValue(bOk and Interface.getString("cclevelup_dual_note") or sWhy);
	if bOk and (not nodeTarget or bNewMode) then
		for _, t in ipairs(CCLevelUp.getNewClassChoices()) do
			if not nodeTarget or DB.getPath(t.node) == L.newclass then
				newclasses.createWindow().setNewClass(t);
			end
		end
	end
	change_header.setVisible(not nodeTarget or bNewMode);
	dual_note.setVisible(not nodeTarget);
	newclasses.setVisible(not nodeTarget or bNewMode);
	cancel_new.setVisible(bNewMode);
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("cclevelup_steps_hp"));
	onPageShow();
end
function onPageShow()
	local L = CCLevelUp.getState();
	if sub_panel.subwindow then
		local w = sub_panel.subwindow;
		w.plan.setValue(CCLevelUp.describeHPRoll());
		w.roll.setVisible(CCLevelUp.needsHPRoll());
		w.result.setValue(L.hp and string.format("Rolled: +%d hit points", L.hp) or "");
	end
end

local _sPath = "";
local _bSetting = false;
function setData(t, bOn)
	_sPath = DB.getPath(t.node);
	level.setValue(tostring(t.level));
	name.setValue(DB.getValue(t.node, "name", ""));
	_bSetting = true;
	pick.setValue(bOn and 1 or 0);
	_bSetting = false;
end
function onPick(bOn)
	if _bSetting then return; end
	if CCLevelUp.toggleSpell(_sPath, bOn) == false then
		_bSetting = true;
		pick.setValue(0);
		_bSetting = false;
	end
	windowlist.window.updateCount();
end
function onOpen()
	Interface.openWindow("spell", DB.getValue(_sPath .. ".officialpath", _sPath));
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("cclevelup_steps_spells"));
	onPageShow();
end
function onPageShow()
	if sub_panel.subwindow then sub_panel.subwindow.onPageShow(); end
end

function updateCount()
	chosen.setValue(CCLevelUp.describeSpellPicks());
end
function refreshList()
	list.closeAll();
	for _, t in ipairs(CCLevelUp.getSpellChoices(search.getValue())) do
		list.createWindow().setData(t, CCLevelUp.isSpellPicked(DB.getPath(t.node)));
	end
	updateCount();
end
function onPageShow()
	-- A button for each list (5e: the class block's Spells toggle).
	local tSets = CCLevelUp.getCasterSets();
	local nSet = CCLevelUp.getSpellSetIndex();
	for i = 1, 3 do
		local c = self["set_" .. i];
		c.setVisible(#tSets > 1 and tSets[i] ~= nil);
		if tSets[i] then
			c.setText(tSets[i].class);
			c.setFrame(i == nSet and "buttondown" or "buttonup", 5, 5, 5, 5);
		end
	end
	lore.setValue(CCLevelUp.hasSpellStep() and "Pick the spells for the new spell slots (double-click a name to read it). Spells already known are not listed." or "This level brings no new spells to choose.");
	refreshList();
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("cclevelup_steps_finish"));
	onPageShow();
end
function onPageShow()
	local tWarnings = CCLevelUp.getWarnings();
	warnings.closeAll();
	for _, s in ipairs(tWarnings) do
		warnings.createWindow().text.setValue(s);
	end
	nowarnings.setVisible(#tWarnings == 0);
	if sub_save.subwindow then sub_save.subwindow.go.setVisible(CCLevelUp.getMissing() == ""); end
	summary.setValue(CCLevelUp.describeSummary());
end
